-- Journeys build plan J9 (the infrastructure half, "J9a") — the mockup host's
-- schema. A demo and a build each gain a `kind` (SITE, as every existing row is,
-- or MOCKUP); a MOCKUP build points at an uploaded zip; `MockupViewGrant` is a
-- viewer's subdomain; `MOCKUP_BUNDLE` is the file class that carries the zip.
-- Generated by `prisma migrate diff`, then hand-extended: the two-step
-- `kind`/`projectId` columns and their backfill, the guard, the CHECKs Prisma
-- cannot express, and the grant-id shape check.
--
-- **Invariant change — `Demo.phaseId`, `Demo.stagingUrl` and `Build.phaseId`
-- become nullable.** Until now a demo always had a phase and a staging URL and
-- a build always had a phase. That is still true of every SITE row, and now the
-- database says so itself (`Demo_site_has_phase_and_url`, `Build_site_has_phase`)
-- instead of leaving it to NOT NULL: a MOCKUP row legitimately has neither, and
-- code that reads either column must narrow on `kind` first. `j9a.test.ts`
-- proves each CHECK by a direct insert.
--
-- **`StoredFile_private_has_owner` is NOT widened.** MOCKUP_BUNDLE is owned by
-- a contract, and a contract is already a valid owner in the T2 form of that
-- CHECK. Recorded here because the brief asked whether it would need to be.

-- CreateEnum
CREATE TYPE "DemoKind" AS ENUM ('MOCKUP', 'SITE');

-- CreateEnum
CREATE TYPE "BuildKind" AS ENUM ('MOCKUP', 'SITE');

-- AlterEnum
ALTER TYPE "FileClass" ADD VALUE 'MOCKUP_BUNDLE';

-- DropIndex
DROP INDEX "Build_projectId_number_key";

-- AlterTable: `kind` and `projectId` land nullable, are backfilled below, and
-- only then become required (as schema.prisma says).
ALTER TABLE "Demo" ADD COLUMN     "contractId" TEXT,
ADD COLUMN     "kind" "DemoKind",
ADD COLUMN     "projectId" TEXT,
ALTER COLUMN "phaseId" DROP NOT NULL,
ALTER COLUMN "stagingUrl" DROP NOT NULL;

-- AlterTable
ALTER TABLE "Build" ADD COLUMN     "bundleFileId" TEXT,
ADD COLUMN     "demoId" TEXT,
ADD COLUMN     "kind" "BuildKind",
ALTER COLUMN "phaseId" DROP NOT NULL;

-- BACKFILL:BEGIN
-- Hand-written. `j9a.test.ts` extracts everything between the BEGIN and END
-- markers and runs it over fixture rows inside a rolled-back transaction; keep
-- every statement of the backfill inside them, and keep it to UPDATEs.
--
-- Every demo and build that exists before this migration is a live staging
-- site. A demo's project is its phase's project (`Demo.phaseId` was NOT NULL
-- until a few lines up, so the subselect always finds one).
UPDATE "Demo" SET "kind" = 'SITE' WHERE "kind" IS NULL;

UPDATE "Demo" AS d
SET "projectId" = (SELECT p."projectId" FROM "Phase" AS p WHERE p."id" = d."phaseId")
WHERE d."projectId" IS NULL;

UPDATE "Build" SET "kind" = 'SITE' WHERE "kind" IS NULL;
-- BACKFILL:END

-- A demo with no project would be unreachable from every query that now reads
-- `Demo.projectId`; refuse rather than guess. Run over a fixture by
-- `j9a.test.ts`, like J4's.
-- VERIFY:BEGIN
DO $$
DECLARE orphans integer;
BEGIN
  SELECT count(*) INTO orphans FROM "Demo" WHERE "projectId" IS NULL;
  IF orphans > 0 THEN
    RAISE EXCEPTION 'J9: % demo(s) have no phase to take a project from; fix them before making Demo.projectId required', orphans;
  END IF;
END $$;
-- VERIFY:END

ALTER TABLE "Demo" ALTER COLUMN "kind" SET NOT NULL,
ALTER COLUMN "kind" SET DEFAULT 'SITE',
ALTER COLUMN "projectId" SET NOT NULL;

ALTER TABLE "Build" ALTER COLUMN "kind" SET NOT NULL,
ALTER COLUMN "kind" SET DEFAULT 'SITE';

-- CreateTable
CREATE TABLE "MockupViewGrant" (
    "id" TEXT NOT NULL,
    "buildId" TEXT NOT NULL,
    "viewerId" TEXT NOT NULL,
    "expiresAt" TIMESTAMP(3) NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "MockupViewGrant_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "MockupViewGrant_buildId_viewerId_idx" ON "MockupViewGrant"("buildId", "viewerId");

-- CreateIndex
CREATE INDEX "MockupViewGrant_viewerId_expiresAt_idx" ON "MockupViewGrant"("viewerId", "expiresAt");

-- CreateIndex
CREATE INDEX "Demo_projectId_idx" ON "Demo"("projectId");

-- CreateIndex
CREATE INDEX "Demo_contractId_idx" ON "Demo"("contractId");

-- CreateIndex
CREATE INDEX "Build_demoId_idx" ON "Build"("demoId");

-- CreateIndex
CREATE INDEX "Build_bundleFileId_idx" ON "Build"("bundleFileId");

-- CreateIndex: mockups are "mockup 2", sites are "version 4", and neither
-- consumes the other's numbers (L3b's "version 2 must mean one thing").
CREATE UNIQUE INDEX "Build_projectId_kind_number_key" ON "Build"("projectId", "kind", "number");

-- AddForeignKey
ALTER TABLE "Demo" ADD CONSTRAINT "Demo_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "Demo" ADD CONSTRAINT "Demo_contractId_fkey" FOREIGN KEY ("contractId") REFERENCES "Contract"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "Build" ADD CONSTRAINT "Build_demoId_fkey" FOREIGN KEY ("demoId") REFERENCES "Demo"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey: Restrict — the bundle is the record of what was shown and
-- approved, so its file row cannot be deleted from under the build.
ALTER TABLE "Build" ADD CONSTRAINT "Build_bundleFileId_fkey" FOREIGN KEY ("bundleFileId") REFERENCES "StoredFile"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "MockupViewGrant" ADD CONSTRAINT "MockupViewGrant_buildId_fkey" FOREIGN KEY ("buildId") REFERENCES "Build"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "MockupViewGrant" ADD CONSTRAINT "MockupViewGrant_viewerId_fkey" FOREIGN KEY ("viewerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- Hand-written CHECKs (house rule 11: Prisma cannot express them). Each is an
-- implication `kind = X ⇒ …` written as `kind <> X OR …`, and each is proven by
-- a direct insert in `j9a.test.ts`. None uses array_length, so the NULL-passes
-- trap in rule 11 does not arise — but note the columns tested here ARE
-- nullable, and `IS NOT NULL` is the whole point: `phaseId <> ''`-style
-- comparisons would evaluate to NULL on a missing value and let it through.

-- A SITE demo is L2's demo: a phase and an HTTPS staging site (the HTTPS rule
-- itself stays in the resolver, where the refusal has a code). A MOCKUP demo
-- carries neither.
ALTER TABLE "Demo" ADD CONSTRAINT "Demo_site_has_phase_and_url"
  CHECK ("kind" <> 'SITE' OR ("phaseId" IS NOT NULL AND "stagingUrl" IS NOT NULL));

-- A SITE build belongs to a phase (L3b), as every build did before this.
ALTER TABLE "Build" ADD CONSTRAINT "Build_site_has_phase"
  CHECK ("kind" <> 'SITE' OR "phaseId" IS NOT NULL);

-- A MOCKUP build without a bundle would be a published iteration with nothing
-- to serve — the mockup router would have a grant, a build and no zip.
ALTER TABLE "Build" ADD CONSTRAINT "Build_mockup_has_bundle"
  CHECK ("kind" <> 'MOCKUP' OR "bundleFileId" IS NOT NULL);

-- The id IS the DNS label the mockup router parses (`grantIdFromHost`): exactly
-- 32 lowercase hex characters. A row whose id the router would refuse to parse
-- is a grant that can never open — a bug worth failing at insert.
ALTER TABLE "MockupViewGrant" ADD CONSTRAINT "MockupViewGrant_id_shape"
  CHECK ("id" ~ '^[0-9a-f]{32}$');
